mapper.update:
update mock_interview_session
set profile_status = 'PROFILE_FAILED',
    profile_error_message = #{errorMessage},
    profile_generated_at = #{now},
    updated_at = #{now}
where id = #{id}

update mock_interview_session
set voice_session_id = #{voiceSessionId},
    status = 'IN_PROGRESS',
    started_at = #{now},
    updated_at = #{now}
where id = #{id}
  and student_id = #{studentId}
  and status = 'PROFILE_READY'

update mock_interview_session
set status = 'FINISHED',
    finished_at = #{now},
    updated_at = #{now}
where id = #{id}
  and student_id = #{studentId}
  and status = 'IN_PROGRESS'
